// 8-G 예외(2번, 11-01): counts 가변 + 키 간격 자릿수(1/4박 v2·1/2박 test) 대응.
// D-3 예외(2번, 11-02): dancePose 곡선 보간(Catmull-Rom + denoised keys).
// dancePoseLinear가 구 선형 경로(A/B·회귀용). 데이터·카운트·bpm 무변경.
import {
  B_ARML, B_ARMR, B_HEAD, B_LEGL, B_LEGR, B_TORSO,
  type BonePose,
} from "../../autoRig";
import { ateez } from "./ateez";
import { a2o } from "./a2o";
import { testTurns } from "./testTurns";
import { smoothedKeys, smoothKey } from "./smooth";
import type { DanceClip, DanceKey } from "./types";

export type { DanceClip, DanceKey } from "./types";
export { ateez, a2o, testTurns };
export { smoothedKeys } from "./smooth";

const CLIPS: DanceClip[] = [ateez, a2o];

/** Pick one of the 2 dances from a seed (DexScene calls once per arrival). */
export function pickDance(seed: number): DanceClip {
  const i = Math.abs(Math.floor(seed)) % CLIPS.length;
  return CLIPS[i];
}

/** Convert 124-BPM DexScene beats to clip-local beats. */
export function danceBeat(beat124: number, clip: DanceClip): number {
  return (beat124 * clip.bpm) / 124;
}

function lerpKey(a: DanceKey, b: DanceKey, t: number, out: BonePose): void {
  const L = (x: number, y: number) => x + (y - x) * t;
  out.rx[B_TORSO] = L(a.torso.rx, b.torso.rx);
  out.ry[B_TORSO] = L(a.torso.ry, b.torso.ry);
  out.rz[B_TORSO] = L(a.torso.rz, b.torso.rz);
  out.sy = L(a.torso.sy, b.torso.sy);
  out.sx = 1 - (out.sy - 1) * 0.5;
  out.sz = 1 - (out.sy - 1) * 0.5;
  out.rx[B_HEAD] = L(a.head.rx, b.head.rx);
  out.rz[B_HEAD] = L(a.head.rz, b.head.rz);
  out.rx[B_ARML] = L(a.armL.rx, b.armL.rx);
  out.rz[B_ARML] = L(a.armL.rz, b.armL.rz);
  out.rx[B_ARMR] = L(a.armR.rx, b.armR.rx);
  out.rz[B_ARMR] = L(a.armR.rz, b.armR.rz);
  out.rx[B_LEGL] = L(a.legL.rx, b.legL.rx);
  out.rz[B_LEGL] = L(a.legL.rz, b.legL.rz);
  out.rx[B_LEGR] = L(a.legR.rx, b.legR.rx);
  out.rz[B_LEGR] = L(a.legR.rz, b.legR.rz);
  // Tail untouched: existing spring delay (blend.ts) drives it.
}

/** Write the interpolated clip pose at a 124-BPM beat into `out`. Loops every clip.counts clip-beats. */
export function dancePose(clip: DanceClip, beat124: number, out: BonePose): BonePose {
  let b = danceBeat(beat124, clip) % clip.counts;
  if (b < 0) b += clip.counts;
  if (clip.counts - b < 1e-9) b = 0; // loop snap: loop end lands exactly on key 0
  const keys = smoothedKeys(clip);
  const pos = b * (keys.length / clip.counts); // key space (v2: x4, test: x2)
  const i0 = Math.floor(pos) % keys.length;
  smoothKey(keys, i0, pos - Math.floor(pos), out);
  return out;
}

/** Pre-D-3 linear path over raw keys (A/B comparison + regression reference). */
export function dancePoseLinear(clip: DanceClip, beat124: number, out: BonePose): BonePose {
  let b = danceBeat(beat124, clip) % clip.counts;
  if (b < 0) b += clip.counts;
  if (clip.counts - b < 1e-9) b = 0; // loop snap: loop end lands exactly on key 0
  const pos = b * (clip.keys.length / clip.counts); // key space (v2: x4, test: x2)
  const i0 = Math.floor(pos) % clip.keys.length;
  const i1 = (i0 + 1) % clip.keys.length;
  lerpKey(clip.keys[i0], clip.keys[i1], pos - Math.floor(pos), out);
  return out;
}

export type DanceRoot = {
  yaw: number; x: number; y: number; z: number;
  headRy: number; // 클립 head.ry + 정면 응시 보정
  torsoRyAdd: number; // 목 한계 초과분 (torso ry에 더함)
};

const TAU = Math.PI * 2;
const HEAD_RY_LIM = 1.22; // 목 한계 ±70°
const ROOT_XZ_LIM = 0.3; // 무대 이탈 방지

function normPi(a: number): number {
  let r = (a + Math.PI) % TAU;
  if (r < 0) r += TAU;
  return r - Math.PI;
}

/**
 * R-B-6: 몸 회전·이동 채널 보간. yaw는 누적 각도 그대로 선형 보간한다
 * (350°→10°를 최단 경로로 감지 않아 돌려차기가 거꾸로 돌지 않음).
 * root·head.ry가 없는 기존 클립은 전부 0으로 동작한다.
 */
export function danceRoot(clip: DanceClip, beat124: number): DanceRoot {
  let b = danceBeat(beat124, clip) % clip.counts;
  if (b < 0) b += clip.counts;
  if (clip.counts - b < 1e-9) b = 0;
  const stepsPerBeat = clip.keys.length / clip.counts; // v2: 4, test: 2
  const pos = b * stepsPerBeat;
  const i0 = Math.floor(pos) % clip.keys.length;
  const i1 = (i0 + 1) % clip.keys.length;
  const t = pos - Math.floor(pos);
  const L = (x: number, y: number) => x + (y - x) * t;
  const ka = clip.keys[i0];
  const kb = clip.keys[i1];
  const yaw = L(ka.root?.yaw ?? 0, kb.root?.yaw ?? 0);
  const x = Math.min(ROOT_XZ_LIM, Math.max(-ROOT_XZ_LIM,
    L(ka.root?.x ?? 0, kb.root?.x ?? 0)));
  const z = Math.min(ROOT_XZ_LIM, Math.max(-ROOT_XZ_LIM,
    L(ka.root?.z ?? 0, kb.root?.z ?? 0)));
  const y = L(ka.root?.y ?? 0, kb.root?.y ?? 0);
  const clipRy = L(ka.head.ry ?? 0, kb.head.ry ?? 0);
  // 1박당 yaw 변화량. 180° 초과면 돌려차기 구간 → 머리 보정 끔.
  const vel = ((kb.root?.yaw ?? 0) - (ka.root?.yaw ?? 0)) * stepsPerBeat;
  const spinning = Math.abs(vel) > Math.PI;
  const yawEff = normPi(yaw);
  if (Math.abs(yawEff) < 1e-3 || spinning) {
    return { yaw, x, y, z, headRy: clipRy, torsoRyAdd: 0 };
  }
  const total = clipRy - yawEff;
  const headRy = Math.min(HEAD_RY_LIM, Math.max(-HEAD_RY_LIM, total));
  return { yaw, x, y, z, headRy, torsoRyAdd: total - headRy };
}
